"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/inline-edit.css";
import { PencilSimple } from "@phosphor-icons/react";
import { useEffect, useId, useRef, useState, type KeyboardEvent } from "react";
import type { BehaviorContract } from "../../lib/behavior-contract";
import { cn } from "../../lib/cn";

export const inlineEditContract: BehaviorContract = {
  input: ["Pointer click", "Enter from trigger", "Programmatic focus"],
  origin: "The read state remains the spatial anchor for the input.",
  enter: "A 120ms opacity swap reveals the input without moving surrounding content.",
  active: "Text is selected once; validation and async saving stay inside the same line box.",
  exit: "The saved value replaces the input and keyboard focus returns to the read state.",
  interruption: "Escape restores the prior value; save failure keeps the draft editable with an inline error.",
  keyboard: ["Enter: edit or save", "Escape: cancel", "Tab: save and continue"],
  reducedMotion: "State swaps immediately while preserving focus behavior.",
};

export type InlineEditProps = {
  value: string;
  onSave: (value: string) => void | Promise<void>;
  label?: string;
  placeholder?: string;
  className?: string;
  disabled?: boolean;
  validate?: (value: string) => string | undefined;
};

export function InlineEdit({ value, onSave, label = "Edit value", placeholder, className, disabled, validate }: InlineEditProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(value);
  const [status, setStatus] = useState<"idle" | "saving" | "error">("idle");
  const [error, setError] = useState("");
  const [announcement, setAnnouncement] = useState("");
  const inputRef = useRef<HTMLInputElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const committingRef = useRef(false);
  const generatedId = useId();
  const errorId = `${generatedId}-error`;

  useEffect(() => setDraft(value), [value]);

  useEffect(() => {
    if (!editing) return;
    inputRef.current?.focus();
    inputRef.current?.select();
  }, [editing]);

  const commit = async (restoreFocus = false) => {
    if (committingRef.current) return;
    committingRef.current = true;
    const next = draft.trim();
    const validationError = !next ? "A value is required." : validate?.(next);
    if (validationError) {
      setStatus("error");
      setError(validationError);
      setAnnouncement(validationError);
      committingRef.current = false;
      return;
    }
    if (next === value) {
      setEditing(false);
      setStatus("idle");
      setAnnouncement("No changes saved");
      committingRef.current = false;
      if (restoreFocus) requestAnimationFrame(() => triggerRef.current?.focus());
      return;
    }
    setStatus("saving");
    setError("");
    try {
      await onSave(next);
      setEditing(false);
      setStatus("idle");
      setAnnouncement(`Saved ${next}`);
      committingRef.current = false;
      if (restoreFocus) requestAnimationFrame(() => triggerRef.current?.focus());
    } catch {
      setStatus("error");
      setError("Could not save. Try again.");
      setAnnouncement("Could not save. Try again.");
      committingRef.current = false;
    }
  };

  const cancel = () => {
    setDraft(value);
    setEditing(false);
    setStatus("idle");
    setError("");
    committingRef.current = false;
    setAnnouncement("Edit cancelled");
    requestAnimationFrame(() => triggerRef.current?.focus());
  };

  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === "Enter") {
      event.preventDefault();
      void commit(true);
    }
    if (event.key === "Escape") {
      event.preventDefault();
      cancel();
    }
  };

  return (
    <div className={cn("whatiuse-inline-edit", className)} data-editing={editing || undefined} data-status={status}>
      {editing ? (
        <>
          <div className="whatiuse-inline-edit__control">
            <input
              ref={inputRef}
              className="whatiuse-inline-edit__input"
              value={draft}
              placeholder={placeholder}
              aria-label={label}
              aria-invalid={status === "error" || undefined}
              aria-describedby={error ? errorId : undefined}
              disabled={status === "saving"}
              onChange={(event) => { setDraft(event.target.value); setStatus("idle"); setError(""); }}
              onKeyDown={onKeyDown}
              onBlur={() => void commit(false)}
            />
            {status === "saving" && <span className="whatiuse-inline-edit__saving" aria-hidden="true"><span className="whatiuse-spinner" /></span>}
          </div>
          {error && <span id={errorId} className="whatiuse-inline-edit__error">{error}</span>}
        </>
      ) : (
        <button
          ref={triggerRef}
          type="button"
          className="whatiuse-inline-edit__value"
          onClick={() => setEditing(true)}
          aria-label={`${label}: ${value}`}
          disabled={disabled}
        >
          <span>{value || placeholder}</span>
          <PencilSimple aria-hidden="true" />
        </button>
      )}
      <span className="whatiuse-sr-only" aria-live="polite">{announcement}</span>
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-spinner { width: 13px; height: 13px; border: 1.5px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: whatiuse-spin 0.75s linear infinite; }

.whatiuse-inline-edit { width: min(420px, 100%); min-height: 44px; }

.whatiuse-inline-edit__value,
.whatiuse-inline-edit__input { width: 100%; height: 44px; padding: 0 10px; border: 1px solid transparent; border-radius: 7px; background: transparent; color: var(--whatiuse-ink); font-size: 22px; font-weight: 570; letter-spacing: -0.035em; text-align: left; }

.whatiuse-inline-edit__value { display: flex; align-items: center; justify-content: space-between; cursor: text; transition: background var(--whatiuse-fast), border-color var(--whatiuse-fast); }

.whatiuse-inline-edit__value:hover { border-color: var(--whatiuse-border-subtle); background: var(--whatiuse-hover); }

.whatiuse-inline-edit__value svg { width: 15px; height: 15px; color: var(--whatiuse-fg-subtle); opacity: 0; transition: opacity var(--whatiuse-fast); }

.whatiuse-inline-edit__value:hover svg,
.whatiuse-inline-edit__value:focus-visible svg { opacity: 1; }

.whatiuse-inline-edit__control { position: relative; }

.whatiuse-inline-edit__input { border-color: var(--whatiuse-border-strong); outline: 0; background: var(--whatiuse-control-surface); box-shadow: 0 0 0 2px var(--whatiuse-border-subtle); }

.whatiuse-inline-edit[data-status="error"] .whatiuse-inline-edit__input { border-color: color-mix(in oklch, var(--whatiuse-fg-danger) 46%, var(--whatiuse-control-border)); box-shadow: 0 0 0 2px color-mix(in oklch, var(--whatiuse-fg-danger) 11%, transparent); }

.whatiuse-inline-edit__saving { position: absolute; top: 0; right: 10px; display: grid; height: 44px; place-items: center; color: var(--whatiuse-fg-muted); }

.whatiuse-inline-edit__error { display: block; padding: 6px 10px 0; color: var(--whatiuse-fg-danger); font-size: 11.5px; font-weight: 520; }

@media (prefers-reduced-motion: reduce) {
.whatiuse-spinner { animation-duration: 2.4s; }
}

@keyframes whatiuse-spin { to { transform: rotate(360deg); } }
}
